/**
 * Block registry. Block ids are stored as Uint8 in chunk data. Each block maps
 * to texture-array layers (top / side / bottom) generated by TextureGen.
 * Pure data: imported by both workers and the main thread.
 */

export enum L {
  ROCK, BASALT, SOIL, MOSS_TOP, MOSS_SIDE, SAND, SNOW, ICE, IRON_ORE, COPPER_ORE,
  QUARTZ, CARBON, TITANIUM_ORE, RADITE, AURELITE, LAVA, METAL_PLATE, GLASS, CONCRETE, LAMP,
  SANDSTONE, ASH, SULFUR, STALK, CANOPY, MUD, BEDROCK, CRYOLITH, LUMINITE, REGOLITH,
  FLOOR, CORAL, SNOW_SIDE, HULL, FUNGUS, RED_ROCK, STALK_TOP, COUNT,
}

export const LAYER_COUNT = L.COUNT as number;

export enum B {
  AIR = 0, BEDROCK, ROCK, BASALT, SOIL, MOSS, SAND, SNOW, ICE, IRON_ORE,
  COPPER_ORE, QUARTZ, CARBON, TITANIUM_ORE, RADITE, AURELITE, LAVA, METAL_PLATE, GLASS, CONCRETE,
  LAMP, SANDSTONE, ASH, SULFUR, STALK, CANOPY, MUD, CRYOLITH, LUMINITE, REGOLITH,
  FLOOR, CORAL, FUNGUS, RED_ROCK, HULL,
  /** invisible solid cell owned by a machine entity */
  MACHINE = 250,
  /** invisible passable cell owned by a machine entity (open door) */
  MACHINE_OPEN = 251,
  UNKNOWN = 255,
}

export interface BlockDef {
  id: number;
  key: string;
  name: string;
  top: number;
  side: number;
  bottom: number;
  /** seconds to break with the Mk1 extractor */
  hardness: number;
  /** minimum extractor tier */
  tier: number;
  drop: string | null;
  dropCount: number;
  solid: boolean;
  opaque: boolean;
  /** rendered in the translucent pass */
  translucent: boolean;
  /** emissive strength (linear HDR multiplier of albedo) */
  emissive: number;
  /** footstep / mining sound family */
  sound: 'rock' | 'soil' | 'sand' | 'snow' | 'ice' | 'metal' | 'glass' | 'crystal' | 'organic';
  /** shows up highlighted by the geological scanner */
  ore: boolean;
  /** radiation emitted (arbitrary units at 1 m) */
  radiation: number;
}

const defs: BlockDef[] = [];

function def(id: number, key: string, name: string, layers: [number, number, number] | number, o: Partial<BlockDef> = {}): void {
  const [top, side, bottom] = typeof layers === 'number' ? [layers, layers, layers] : layers;
  defs[id] = {
    id, key, name, top, side, bottom,
    hardness: 0.6, tier: 1, drop: key, dropCount: 1, solid: true, opaque: true,
    translucent: false, emissive: 0, sound: 'rock', ore: false, radiation: 0,
    ...o,
  };
}

def(B.AIR, 'air', 'Vácuo', 0, { solid: false, opaque: false, drop: null });
def(B.BEDROCK, 'bedrock', 'Manto Planetário', L.BEDROCK, { hardness: Infinity, drop: null, tier: 99 });
