def(B.SAND, 'sand', 'Areia', L.SAND, { hardness: 0.3, sound: 'sand' });
def(B.SNOW, 'snow', 'Neve', [L.SNOW, L.SNOW_SIDE, L.SOIL], { hardness: 0.25, sound: 'snow', drop: 'ice' });
def(B.ICE, 'ice', 'Gelo', L.ICE, { hardness: 0.5, sound: 'ice' });
def(B.IRON_ORE, 'iron_ore', 'Minério de Ferro', L.IRON_ORE, { hardness: 1.1, drop: 'iron', ore: true });
