def(B.RADITE, 'radite', 'Radita', L.RADITE, { hardness: 1.4, drop: 'radite', ore: true, emissive: 0.35, sound: 'crystal', radiation: 1.2 });
def(B.AURELITE, 'aurelite', 'Aurelita', L.AURELITE, { hardness: 1.3, drop: 'aurelite', ore: true, emissive: 0.9, sound: 'crystal' });
def(B.LAVA, 'lava', 'Lava Solidificando', L.LAVA, { hardness: 1.2, drop: 'basalt', emissive: 2.6 });
def(B.METAL_PLATE, 'metal_block', 'Painel Metálico', L.METAL_PLATE, { hardness: 0.9, sound: 'metal' });
def(B.GLASS, 'glass', 'Vidro Reforçado', L.GLASS, { hardness: 0.5, opaque: false, translucent: true, sound: 'glass' });
def(B.CONCRETE, 'concrete', 'Compósito Estrutural', L.CONCRETE, { hardness: 1.0 });
