def(B.STALK, 'stalk', 'Caule Alienígena', [L.STALK_TOP, L.STALK, L.STALK_TOP], { hardness: 0.5, drop: 'organics', sound: 'organic' });
def(B.CANOPY, 'canopy', 'Copa Bioluminescente', L.CANOPY, { hardness: 0.15, drop: 'organics', sound: 'organic', emissive: 0.25 });
def(B.MUD, 'mud', 'Lama', L.MUD, { hardness: 0.3, sound: 'soil', drop: 'soil' });
def(B.CRYOLITH, 'cryolith', 'Criolita', L.CRYOLITH, { hardness: 1.6, drop: 'cryolith', ore: true, emissive: 0.3, sound: 'crystal' });
