def(B.MACHINE_OPEN, 'machine_open', 'Passagem', 0, { opaque: false, solid: false, drop: null, hardness: Infinity });

const fallback = defs[B.ROCK];
export const BLOCKS: BlockDef[] = [];
for (let i = 0; i < 256; i++) BLOCKS[i] = defs[i] ?? fallback;

export function blockSolid(id: number): boolean {
  return BLOCKS[id].solid;
}

/** Placeable block for an item key (if any). */
export const ITEM_TO_BLOCK: Record<string, number> = {
  rock: B.ROCK, basalt: B.BASALT, soil: B.SOIL, sand: B.SAND, ice: B.ICE,
  metal_block: B.METAL_PLATE, glass: B.GLASS, concrete: B.CONCRETE, lamp: B.LAMP,
  floor: B.FLOOR, hull_block: B.HULL,
};

/** Packed lookup tables for fast access in the mesher. */
export const BLOCK_OPAQUE = new Uint8Array(256);
export const BLOCK_TRANSLUCENT = new Uint8Array(256);
export const BLOCK_SOLID = new Uint8Array(256);
export const BLOCK_LAYERS = new Uint8Array(256 * 3);
export const BLOCK_EMISSIVE = new Float32Array(256);
for (let i = 0; i < 256; i++) {
  const b = BLOCKS[i];
  BLOCK_OPAQUE[i] = b.opaque ? 1 : 0;
  BLOCK_TRANSLUCENT[i] = b.translucent ? 1 : 0;
  BLOCK_SOLID[i] = b.solid ? 1 : 0;
  BLOCK_LAYERS[i * 3] = b.top;
  BLOCK_LAYERS[i * 3 + 1] = b.side;
  BLOCK_LAYERS[i * 3 + 2] = b.bottom;
  BLOCK_EMISSIVE[i] = b.emissive;
}
BLOCK_OPAQUE[B.UNKNOWN] = 1;
BLOCK_SOLID[B.UNKNOWN] = 1;
